const S={uid:'',week:monday(day()),date:'',manager:'',view:'tasks',kind:'',status:'unfinished',range:'all',search:'',limit:50,rows:[],clientRows:[],revision:0,events:new Map(),assignments:[],managers:[],selected:'',sub:'shipment',contracts:[],scans:[],shelfPlans:[],feed:null,error:'',message:'',loaded:false,busy:false,mobile:false,brief:'',summaryOpen:false,recording:false,voiceTarget:'shelf',recordBusy:false,pendingClips:[],drafts:new Map()};
let searchTimer=null;
let refreshToken=0,recorder=null,stream=null,recordTimer=null,queue=Promise.resolve(),recordStarted=0,resumePremium=false;
