function stateOf(e){const c=contract(e.t);if(!e.a&&e.t.done&&e.t.closed_by==='CRM'&&/замен[её]н|системно закрыта/i.test([e.t.fact_result,e.t.done_comment].join(' ')))return 'replaced';if(e.a?.cancelled||c?.state==='cancelled')return 'cancelled';if(e.t.review_status==='stale_review')return 'review';if(e.t.review_status==='pending')return 'pending';if(e.a?.kind==='potential')return e.a.completed_at?'done':'open';if(c)return c.state==='verified'?'done':c.check_issue?'check':c.state==='not_achieved'?'failed':Number(c.progress_pct)>0?'partial':'open';return e.t.done?'done':'open';}
function overdue(t){const a=assignment(t),c=contract(t),e={t,a};if(['done','cancelled','pending','review','replaced'].includes(stateOf(e)))return false;if(c){return !c.check_issue&&Date.parse(c.control_at)<Date.now();}try{if(typeof isTaskOverdue==='function')return isTaskOverdue(t);}catch{}return !!t.due_date&&t.due_date<day();}
function entries(){return allEntries().filter(e=>(S.status!=='unfinished'||!['done','cancelled','pending','review','replaced'].includes(stateOf(e)))&&(S.range!=='week'||inWeek(e))&&(!S.kind||kindOf(e)===S.kind)&&(!S.status||S.status==='unfinished'||(S.status==='overdue'?overdue(e.t):S.status==='shelf'?S.shelfPlans.some(p=>p.task_id===e.t.id):stateOf(e)===S.status))&&(!S.search||[e.c.name,e.t.title,e.t.text,e.t.manager_name,...(e.t.ai_stock_items||[]).map(x=>[x.sku,x.product].join(' '))].join(' ').toLowerCase().includes(S.search.toLowerCase()))).sort((a,b)=>String(b.t.created_at||b.t.due_date||'').localeCompare(String(a.t.created_at||a.t.due_date||''))||String(a.t.id).localeCompare(String(b.t.id)));}
function taskLabel(e){if(!e.t)return tag('Предложение по визиту');const state=stateOf(e),verified=contract(e.t)?.state==='verified';return tag(({done:verified?'Выполнено · подтверждено 1С':e.a?'Выполнено · результат менеджера':'Выполнено · сохранённая отметка',partial:'Частично выполнено',check:'Проверить данные',failed:'Не выполнено к сроку',open:overdue(e.t)?'Просрочено':'В работе',cancelled:'Отменено',review:'Требует разбора',replaced:'Заменено другой задачей',pending:'Ожидает утверждения'})[state],state==='done'?'good':['partial','check','failed'].includes(state)?'review':'');}
function label(e){const plan=S.shelfPlans.find(p=>p.route_id===(e.r?.id||assignment(e.t)?.route_id)&&p.client_id===e.c?.id);return taskLabel(e)+(plan?' '+tag(plan.scan_id?'Полка ✓':'Полка · обязательна',plan.scan_id?'good':''):'');}
function routeAgenda(){if(S.view!=='tasks')return '';const routes=currentRoutes().filter(r=>!network(r)&&(!S.kind||(client(r.client_id)?.client_status==='Потенциальный'?'potential':'work')===S.kind)).sort((a,b)=>a.visit_date.localeCompare(b.visit_date)||a.manager_name.localeCompare(b.manager_name,'ru')||(a.sort_order||0)-(b.sort_order||0));return '<details class="tr-panel tr-route-agenda"'+(!boss()?' open':'')+'><summary><b>Клиенты маршрута недели · '+routes.length+'</b></summary><p class="tr-sub">Сохранённые руководителем визиты. Задачи на продажу и их проценты учитываются отдельно после утверждения.</p><div class="tr-table-wrap"><table><thead><tr><th>День / менеджер</th><th>Торговая точка</th><th>Задача</th></tr></thead><tbody>'+routes.map(r=>{const assigned=S.assignments.filter(a=>a.route_id===r.id&&!a.cancelled);return '<tr><td>'+esc(pretty(r.visit_date))+'<br>'+esc(r.manager_name)+'</td><td><b>'+esc(r.client_name)+'</b><br>'+esc(r.city||'')+' · '+esc(r.address||'')+'</td><td>'+(assigned.length?assigned.map(a=>{const t=scopedTasks().find(t=>t.id===a.task_id);return t?'<button data-tr="route-task" data-value="t:'+esc(t.id)+'">'+esc(t.title||'Открыть задачу')+'</button>':'Задача поставлена';}).join('<br>'):'Задача ещё не поставлена')+'</td></tr>';}).join('')+'</tbody></table></div>'+(!routes.length?'<p>На выбранную неделю нет сохранённых клиентских визитов.</p>':'')+'</details>';}
function metrics(){const es=taskEntries().filter(e=>stateOf(e)!=='pending'),work=es.filter(e=>kindOf(e)==='work'),leads=es.filter(e=>kindOf(e)==='potential');const plans=S.shelfPlans.filter(p=>es.some(e=>e.t.id===p.task_id));const metric=(name,n,total,kind)=>'<button class="tr-panel" data-tr="metric" data-value="'+kind+'"><div class="tr-sub">'+name+'</div><div class="tr-number">'+(total?Math.round(n/total*100)+'%':'—')+'</div><div>'+n+' из '+total+'</div><div class="tr-meter"><span style="width:'+(total?n/total*100:0)+'%"></span></div></button>';return '<p class="tr-sub">План выбранной недели: выполненные задачи / поставленные задачи. Сверка полки считается отдельно.</p><div class="tr-metrics">'+metric('Задачи по рабочим клиентам',work.filter(e=>stateOf(e)==='done').length,work.length,'work')+metric('Задачи по потенциальным клиентам',leads.filter(e=>stateOf(e)==='done').length,leads.length,'potential')+metric('Проверка полки',plans.filter(p=>p.scan_id).length,plans.length,'shelf')+'</div>';}
function managerBars(){const es=taskEntries().filter(e=>stateOf(e)!=='pending');return '<section class="tr-panel tr-stack"><h3>Выполнение задач по менеджерам</h3>'+[...new Set(es.map(e=>e.t.manager_name))].map(name=>'<h4>'+esc(name)+'</h4>'+[['work','Рабочие'],['potential','Потенциальные']].map(([kind,label])=>{const a=es.filter(e=>e.t.manager_name===name&&kindOf(e)===kind),done=a.filter(e=>stateOf(e)==='done').length,partial=a.filter(e=>stateOf(e)==='partial').length;if(!a.length)return '';return '<button class="tr-bar" data-tr="bar-manager" data-kind="'+kind+'" data-value="'+esc(name)+'"><b>'+label+'</b><span class="tr-meter"><span style="width:'+done/a.length*100+'%"></span><span class="tr-partial" style="width:'+partial/a.length*100+'%"></span></span><span>'+Math.round(done/a.length*100)+'% · '+done+'/'+a.length+'</span><span class="tr-sub">'+(kind==='work'?partial+' частично':'Завершённые этапы')+'</span></button>'}).join('')).join('')+'<div class="tr-sub">Синий — выполнено · охра — частично. Новые продажи подтверждает 1С. Старые результаты сохранены как отметки менеджеров, без приписывания подтверждения 1С. Частичное выполнение не считается полным; отменённые задачи не засчитываются выполненными. '+(es.length?'':'На выбранную неделю задачи пока не поставлены.')+'</div></section>';}
