const emptyBatchCost=()=>({input_tokens:0,output_tokens:0,cached_input_tokens:0,model_calls:0,cost_usd:0,reported:false});
const B={open:false,phase:'',busy:false,stop:false,manager:'',date:'',week:'',rows:[],step:'manager',saved:new Map(),reopen:false,cost:emptyBatchCost(),costEpoch:0,coverage:null,coverageManager:'',coverageWeek:'',coverageError:''};
const batchRequestId=()=>w.crypto?.randomUUID?.()||'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const n=Math.floor(Math.random()*16);return (c==='x'?n:(n&3)|8).toString(16)});
function batchCost(response,epoch){if(epoch!==B.costEpoch)return;const usage=response?.usage;if(!usage)return;B.cost.reported=true;if(response.cache_hit||response.cached)return;for(const key of ['input_tokens','output_tokens','cached_input_tokens','model_calls','cost_usd']){const n=Number(usage[key]);if(Number.isFinite(n)&&n>0)B.cost[key]+=n;}}
const batchWorkspace=(action,e,payload={})=>{const epoch=B.costEpoch;return workspace(action,e,payload,response=>batchCost(response,epoch));};
function batchCostHtml(){return '<details class="tr-sub tr-batch-cost"><summary>Расход этого открытия: '+(B.cost.reported?esc(B.cost.cost_usd.toFixed(6).replace('.',','))+' $':'сведения ещё не получены')+'</summary>Вызовов модели: '+B.cost.model_calls+' · вход: '+B.cost.input_tokens+' · выход: '+B.cost.output_tokens+' · из кеша: '+B.cost.cached_input_tokens+' токенов. Поиск в прайсе и проверка плана не вызывают платную подготовку.</details>';}
function manualBatchPlan(row){row.plan={version:5,operation:'create',client_id:row.e.c.id,route_id:row.e.r.id,manager_name:row.e.r.manager_name,route_day:row.e.r.visit_date,title:'',basis:'',expected_result:'',stage:row.e.c.client_status==='Потенциальный'?'profile':'shipment',items:[]};row.selected=false;row.edit=true;row.error='';row.status='Ручной черновик';}
function reviewedBatchPlan(row,response){if(response?.persistence)row.persistence=response.persistence;row.pending=response?.mode==='pending';if(response?.mode==='existing_draft'){row.draftRef=response.draft_ref;row.selected=false;row.edit=false;row.error='';row.status='Черновик по юрлицу сохранён для другого визита';return false;}if(response?.mode==='existing'){row.done=true;row.selected=false;row.edit=false;row.error='';row.existing=response.existing||{};row.status=row.existing.reason==='legal_week'?'У юрлица уже есть задача на этой неделе':'Задача по этому визиту уже поставлена';return false;}if(row.pending){row.selected=false;row.status='Подготовка уже идёт. Продолжите позже: повторной оплаты не будет.';row.error='';return false;}if(response?.draft&&['prepared','editable'].includes(response.mode)){row.plan={...response.draft,items:Array.isArray(response.draft.items)?response.draft.items:[]};const moved=response.persistence?.scope_changed===true;row.selected=response.mode==='prepared'&&!!response.approval_token&&!moved;row.edit=moved||response.mode==='editable'||!row.selected||row.edit;row.notice=moved?'Визит перенесён. Проверьте сохранённое предложение':response.persistence?.reused?'Восстановлен сохранённый проект'+(response.persistence.created_at?' · '+pretty(String(response.persistence.created_at).slice(0,10)):''):'';row.status=moved?'Проверьте сохранённое предложение':row.selected?'Готово':'Нужно исправить черновик';row.error=row.selected||moved&&response.mode==='prepared'?'':errorText(response.validation_error||response.question||'TASK_TARGETS_INVALID');return row.selected;}row.selected=false;row.edit=!!row.plan;row.status='Нужно уточнение';row.error=errorText(response?.question||response?.validation_error||'Недостаточно данных для предложения');return false;}
const batchSavedKey=(manager,date,week=S.week)=>manager+'|'+(date==='week'?week+'|week':date);
function saveBatch(){if(B.rows.length&&B.manager&&B.date)B.saved.set(batchSavedKey(B.manager,B.date,B.week||S.week),B.rows);}
function batchRoutes(){return values('routes').filter(r=>r.visit_date>=S.week&&r.visit_date<=plus(S.week,6)&&!r.removed&&!r.is_office_day&&(r.approved||r.review_status==='approved')&&S.managers.some(m=>m.name===r.manager_name));}
function batchEntries(manager,date){if(!B.coverage||B.coverageManager!==manager||B.coverageWeek!==S.week)return [];const seen=new Set(),entries=batchRoutes().filter(r=>r.manager_name===manager&&(date==='week'||r.visit_date===date)&&!network(r)).sort((a,b)=>a.visit_date.localeCompare(b.visit_date)||(a.sort_order||0)-(b.sort_order||0)).flatMap(r=>routeIds(r).map(id=>({key:'r:'+r.id+':'+id,c:client(id),r}))).filter(e=>{e.coverage=B.coverage.find(x=>x.route_id===e.r.id&&x.client_id===e.c?.id);if(!e.c||e.c.manager_name!==manager||!['Рабочий','Потенциальный'].includes(e.c.client_status)||seen.has(e.key)||!e.coverage||e.coverage.existing||S.assignments.some(a=>a.route_id===e.r.id&&a.client_id===e.c.id&&!a.cancelled))return false;seen.add(e.key);return true;});const owners=new Map();for(const e of entries){const ref=e.coverage.draft_ref;if(ref&&(ref.route_id!==e.r.id||ref.client_id!==e.c.id))e.draftRef=ref;if(e.c.client_status==='Рабочий'&&e.coverage.legal_key){const key=e.coverage.legal_key,owner=owners.get(key);if(ref){owners.set(key,ref);}else if(!owner)owners.set(key,{route_id:e.r.id,client_id:e.c.id,route_day:e.r.visit_date,manager_name:e.r.manager_name,state:'local'});}}for(const e of entries){const ref=e.c.client_status==='Рабочий'?owners.get(e.coverage.legal_key):null;if(ref&&(ref.route_id!==e.r.id||ref.client_id!==e.c.id))e.draftRef=ref;}return entries;}
async function loadBatchCoverage(manager){B.busy=true;B.phase='coverage';B.coverage=null;B.coverageManager=manager;B.coverageWeek=S.week;B.coverageError='';B.step='coverage';paint();try{const rows=await rpc('crm_task_route_coverage_v1',{p_manager:manager,p_week:S.week});if(!Array.isArray(rows))throw Error('Не удалось проверить уже поставленные задачи.');B.coverage=rows;}catch(e){B.coverageError=errorText(e);}finally{B.busy=false;B.phase='';B.step='day';if(B.reopen){B.reopen=false;openBatch();}paint();}return !!B.coverage;}
function savedBatchRow(e){for(const rows of B.saved.values()){const old=rows.find(x=>x.e.key===e.key&&x.e.r.visit_date===e.r.visit_date&&x.e.r.manager_name===e.r.manager_name);if(old)return old;}return null;}
const batchPeriod=()=>B.date==='week'?pretty(B.week)+' — '+pretty(plus(B.week,6)):pretty(B.date);
