async function rpc(name,args){const r=await db.rpc(name,args);if(r.error)throw Error(r.error.message);return r.data;}
async function assistant(action,e,text=''){if(!e?.c)throw Error('Выберите клиента');const d=draft(e);d.pending=true;paint();try{const r=await db.functions.invoke('crm-tasks-assistant-v4',{body:{action,client_id:e.c.id,task_id:e.t?.id,route_id:e.r?.id,transcript:text}});if(r.error||r.data?.error){let message=r.data?.error;try{message=message||(await r.error?.context?.json())?.error;}catch{}throw Error(message||r.error?.message||'Не удалось выполнить запрос');}return r.data;}finally{d.pending=false;}}
