async function openAgentRoute(data){
 if(!allowed()||!boss())throw Error('TASK_CREATE_FORBIDDEN');
 if(B.busy)throw Error('Сейчас готовится маршрут. Дождитесь завершения или остановите подготовку.');
 if(!S.loaded)await refresh();
 if(!S.managers.some(x=>x.name===data.manager)||!/^\d{4}-\d{2}-\d{2}$/.test(data.date))throw Error('TASK_ROUTE_REQUIRED');
 const r=await db.from('route_plans').select('*').eq('manager_name',data.manager).eq('visit_date',data.date).limit(1000);
 if(r.error)throw r.error;
 const rs=(r.data||[]).filter(x=>data.route_ids.includes(x.id)&&!network(x)&&!x.removed&&(x.approved||x.review_status==='approved'));
 if(!rs.length)throw Error('TASK_ROUTE_REQUIRED');
 const ids=[...new Set(rs.flatMap(routeIds))],cs=await db.from('clients').select('*').in('id',ids);
 if(cs.error)throw cs.error;
 for(const c of cs.data||[]){const old=allClients.find(x=>x.id===c.id);if(old)Object.assign(old,c);else allClients.push(c);}
 for(const route of rs){const old=allRoutePlans.find(x=>x.id===route.id);if(old)Object.assign(old,route);else allRoutePlans.push(route);}
 S.week=monday(data.date);S.manager=data.manager;S.range='week';S.status='unfinished';S.kind='';S.search='';
 w.goPage?.('tasks','Задачи');openBatch();B.manager=data.manager;
 // Preparation has no writes; explicit approval uses the same reviewed batch UI.
 void batchAction('batch-day',data.date).catch(e=>{S.error=errorText(e);paint();});paint();
}
